91	// GetTranscriptPosition returns the current line count of a Codex rollout transcript.
92	func (c *CodexAgent) GetTranscriptPosition(path string) (int, error) {
93		if path == "" {
94			return 0, nil
95		}
96	
97		file, err := os.Open(path) //nolint:gosec // Path comes from agent hook input
98		if err != nil {
99			if os.IsNotExist(err) {
100				return 0, nil
101			}
102			return 0, fmt.Errorf("failed to open transcript: %w", err)
103		}
104		defer file.Close()
105	
106		reader := bufio.NewReader(file)
107		lineCount := 0
108		for {
109			line, readErr := reader.ReadBytes('\n')
110			if readErr != nil {
111				if readErr == io.EOF {
112					if len(line) > 0 {
113						lineCount++
114					}
115					break
116				}
117				return 0, fmt.Errorf("failed to read transcript: %w", readErr)
118			}
119			lineCount++
120		}
121		return lineCount, nil
122	}
